    body: `
はい、オーストラリアで現金払いの仕事をした場合、タックスリターンを提出する必要があります。現金支払いも、銀行振込の給料と同じく課税所得です。違いは、支払い時にPAYG税が源泉徴収されないだけ。会計年度末に収入を申告し、支払うべき税金を支払う責任があなたにあります。現金収入を申告しないことは脱税です。当社チームは現金払い業務に関わるタックスリターンを定期的に対応しています。

## 現金払い仕事は税金にどう影響する？

現金で支払われると：

- 支払い時にPAYG税が源泉徴収されない
- ATOの給与計算報告システムに記録が残らない
- 全額を受け取るが、税負担はあなたに移る
- 年度末に自分でタックスリターンで収入を申告

つまり、現金収入に15%ワーキングホリデーメーカー税率の税金がかかる可能性があり、PAYGではなく提出時に支払うことになります。

## どんな記録を保管すべき？

PAYG記録がないので、自分の記録が重要です：

- 働いた日付（各シフトを記録）
- シフトごとの労働時間
- 合意した時給
- 各支払いで受け取った金額
- 支払った人物または企業の名前と連絡先
- 業務を確認するメッセージ、メール、シフト通知

これらの記録を撮影またはスキャンし、安全な場所に保管。ATOは5年後まで要求できます。

## 現金払い仕事のスーパーは？

[ABN](/ja/abn)の請負業者ではなく、現金で支払われる従業員だった場合、雇用主は給料に加えて12%のスーパーを支払う法的義務があります。現金払いの雇用主の多くがこれを行いません。オーストラリアの雇用法に対する重大な違反です。

未払いスーパーがある場合：

- 労働時間と給料のすべての記録を保管
- [当社チームにお問い合わせ](/ja/contact)。問題提起をサポートします
- 当社はクライアントの回収プロセスを定期的に対応

数週間から数ヶ月働いた場合、回収できる金額は大きいことがあります。

## 給与明細がもらえなかった場合は？

現金契約で給与明細がないことは残念ながら一般的です。回避策：

- 自分の記録を収入申告の基礎として使用
- 正直で一貫性のある申告（正確な数字がない時は推定）
- 業務の証拠を保管（入金した現金を示す銀行入金、テキストのやり取り、職場の写真）

少し不正確な数字でも誠実な申告のほうが、提出しないよりずっと良いです。ATOは、誠意ある推定エラーよりも、意図的な未開示にはるかに厳しいです。

## 当社サービスの現金収入対応

当社で提出する場合：

- 正しい15%ワーキングホリデーメーカー税率で現金収入を申告
- 正確な納税額（あれば）を算出
- 業務関連控除を申請して税金を減らす
- 従業員だった場合、未払いスーパーの回収もサポート

[情報をお送りください](/ja/contact)。記録が不完全でも、申告書の最適な処理方法を見極めます。
 `,
