    description: '還付金は年間で税金を払い過ぎていた場合にATOが返してくれるお金です。ワーホリの平均還付金額と確認方法を解説します。',
    body: `
タックスリフォンド（還付金）は、年間に給料から源泉徴収された税金が実際の納税額を超えた場合、オーストラリア税務署（ATO）が返してくれるお金です。多くのワーキングホリデーメーカーが還付金を受け取るのは、雇用主が必要以上に税金を源泉徴収するからです（TFNがない期間や、会計年度の一部しか働かなかった場合など）。還付金は通常、提出から2週間以内にオーストラリアの銀行口座に振り込まれます。当社チームは提出前に予想還付額を計算するので、何を期待するか分かります。

## なぜ多くのワーキングホリデーメーカーが還付を受けるのか

通常、いくつかの要因で還付になります：

- 会計年度の一部しか働かなかった（雇用主の源泉徴収は通年の見積もりに基づく）
- TFNなしの期間（15%ではなく45%源泉徴収）
- 未登録雇用主の期間（15%ではなく30%源泉徴収）
- 課税所得を減らす対象控除
- メディケア税免除（課税所得の2%を節約）

その年に長く働いたほど、源泉徴収の問題が多かったほど、典型的な還付額は大きくなります。

## 還付対象か確認する方法

正確に知る唯一の方法は、タックスリターンを準備すること：

- ATOシステムからインカムステートメントを取得
- 15%税率で実際の納税額を計算
- 源泉徴収額と比較
- 対象となる控除とメディケア税免除を追加
- 提出前に還付額を確認

おおよその見積もりとして、当社が提出するほとんどのワーキングホリデーメーカーは$1,000〜$3,000の還付を受けます。一部はそれ以上で、滞在期間、源泉徴収が高かった期間、対象控除によって変わります。

## ATOはいつ還付金を支払う？

タイムライン：

- 電子的に提出（当社は常に電子提出）
- ATOがほとんどの場合2週間以内に処理
- それより早いこともあります（数営業日）
- 還付金が指定したオーストラリアの銀行口座に直接振り込まれる

ピークシーズン（8月/9月）の還付金は数日遅れることがあります。当社は提出ステータスをモニタリングし、還付金が発行されたらお知らせします。

## オーストラリアを離れた後でも還付を受けられる？

はい。海外からの提出は、当社のサービスで全く同じように機能します：

- 当社がリモートで申告書を準備・提出
- 還付金がオーストラリアの銀行口座に振り込まれる
- 還付金がクリアするまでその口座を開いたままに

オーストラリアの銀行口座がすでに閉鎖されている場合、[当社チームにお問い合わせ](/ja/contact)。代替手段をご相談します。

## 還付金を最大化する方法

合法的に最大の還付金を得るために：

- 対象となるすべての控除を把握するため、当社チームを通じて提出
- メディケア税免除を申請（メディケア対象外の場合）
- 年間を通じて業務関連経費を記録
- 制服、工具、業務関連の移動の領収書を保管
- 雇用主から払い戻されていない業務経費の記録を保管

当社は自己提出時に見落とすかもしれない控除を特定します。結果として、通常意味のある大きな還付額になります。
 `,
