  'fair-work-act-working-holiday-makers': {
    title: 'Fair Work Act（公正労働法）：ワーホリも守られる労働者の権利',
    description: 'Fair Work Actはオーストラリアの主要な労働法。ワーキングホリデー保持者にも適用される権利を解説します。',
    body: `
Fair Work Act 2009はオーストラリアの主要な雇用法です。オーストラリア市民に適用されるのとまったく同じようにワーキングホリデーメーカーに適用されます。Actは、最低賃金、有給祝日、年次休暇、不公正解雇からの保護を含む11の最小資格を保証するNational Employment Standards（NES）を確立します。ワーキングホリデーメーカーは、ビザステータスに関係なくActの完全なカバレッジを持ちます。当社チームは、権利の理解と雇用主との問題の対処をお手伝いします。

## Fair Work Actが保証するもの

Actは11の最小資格であるNational Employment Standards（NES）を確立し、ビザステータスに関係なくすべての従業員に適用：

1. 最大週次労働時間（38時間プラス合理的な追加時間）
2. 柔軟な労働取り決めを要求する権利
3. 育児休暇規定
4. 年次休暇（正社員には年4週間、カジュアルには代わりにカジュアル・ローディング）
5. 個人/介護休暇（正社員には年10日）
6. 地域奉仕休暇（陪審員義務、緊急サービスボランティア）
7. 長期勤続休暇
8. 祝日（正社員には有給、働く場合のペナルティレート）
9. 解雇通知
10. 整理退職金（資格のある従業員）
11. Fair Work Information Statement（雇用主が提供する必要）

加えて、少なくとも全国最低賃金または該当するアワード率を受け取る権利。

## NESがワーキングホリデーメーカーに実務的にどう適用される？

バックパッカーには、最も関連性の高い資格は：

- **最低賃金**：正社員には時給$24.95、カジュアルには時給$31.19（2025年7月1日から）
- **祝日**：働く時は約225%のペナルティレート、または働かない時は基本率の支払い（正社員のみ）
- **解雇通知**：雇用終了時の適切な通知または代替支払い
- **最大週次時間**：不合理な追加時間を要求されない保護
- **アワード率**：ほとんどの労働者は最低より高い率のアワードでカバー

ワーキングホリデーメーカーは通常、年次休暇資格を得るのに十分な勤続を蓄積しませんが、賃金と条件の保護はすべて初日から適用されます。

## Fair Work Ombudsmanとは

Fair Work Ombudsman（FWO）は、Fair Work Actの執行を担当する政府機関です。FWOは：

- 労働者からの苦情を調査
- 従業員と雇用主間の紛争を調停
- Actを侵害する雇用主に対して法的措置を取る
- 移民労働者向けに翻訳されたリソースを提供

Fair Work Actの下での権利が侵害されていると信じる場合、[当社チームにお問い合わせ](/ja/contact)。当社は、ワーキングホリデーメーカーが何が支払われるべきかを特定し、正しいチャネルを通じて問題を提起するのをお手伝いします。

## 雇用主の報告がビザに影響する？

いいえ。オーストラリア政府は、職場違反を報告する一時ビザ保持者に特定の保護があります：

- Workplace Justice Visa規定は、一時ビザ保持者が職場苦情を追求するためにオーストラリアに残ることを許可
- ビザはルール違反に基づいてキャンセルされない、報告のために
- 報復は違法

これらの保護は、雇用主が職場苦情を恐れて違法行為をエスカレートしないことを意味します。
 `,
  },

